-- Discover's lists for the UI review, in the seeded clone (review.sh setup).
--
-- Real titles and posters from TheTVDB's filter endpoints, as the daily job
-- stored them on 2026-11-25 (English originals; a poster, a score of at least
-- 100 and a sane year), trimmed to a few dozen a list (a genre list to thirty
-- titles of the last five years and thirty older ones). DiscoverListsTimer is
-- switched off in every review instance, so no run asks TheTVDB for them.
--
-- The rows depend on the date, so the lists are dated from the day of the run:
-- "{year}" in a key becomes this year; "New series" premiered in the last 80
-- days, two days apart, in TheTVDB's order; "Popular from" premiered on
-- January 1 and "Movies from" are this year's; the all-time and genre lists
-- keep their own years (a genre row puts the last five years first).
--
-- Regenerate from a database where the job has run (with genre lists for the
-- seeded user's top two genres) rather than editing titles by hand.

TRUNCATE discover_list, discover_dismissal;

CREATE TEMP TABLE ui_review_discover (key_pattern text, position int, title jsonb);


SELECT replace(key_pattern, '{year}', extract(year FROM current_date)::int::text),
       jsonb_agg(
           CASE
               WHEN key_pattern = 'series-new-{year}' THEN
                   title || jsonb_build_object(
                       'firstAired', to_char(current_date - position * 2, 'YYYY-MM-DD'),
                       'year', extract(year FROM current_date - position * 2)::int)
               WHEN key_pattern = 'series-popular-{year}' THEN
                   title || jsonb_build_object(
                       'firstAired', to_char(make_date(extract(year FROM current_date)::int, 1, 1), 'YYYY-MM-DD'),
                       'year', extract(year FROM current_date)::int)
               WHEN key_pattern = 'movie-year-{year}' THEN
                   title || jsonb_build_object('year', extract(year FROM current_date)::int)
               ELSE title
           END
           ORDER BY position),
       count(*),
       now()
FROM ui_review_discover
GROUP BY key_pattern;

DROP TABLE ui_review_discover;
